window.WORD_AI_EXAMPLE_CHUNK = {"entries":{"practical":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"实用性的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"实际的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"现实的"}],"examples":[{"sentence":"The committee chose a practical solution that could be maintained by local staff.","translation":"委员会选择了一个可由当地人员维护的实用方案。","targetForm":"practical","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Practical training helped the volunteers respond calmly when the emergency alarm sounded.","translation":"实际训练帮助志愿者在紧急警报响起时冷静应对。","targetForm":"practical","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Her practical advice focused on reducing costs without lowering the quality of care.","translation":"她的务实建议着重于在不降低照护质量的前提下减少成本。","targetForm":"practical","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"A practical limitation of the plan is that rural clinics lack reliable internet access.","translation":"该计划的一个现实限制是农村诊所缺乏稳定的互联网接入。","targetForm":"practical","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The handbook offers practical ways to protect confidential information during fieldwork.","translation":"这本手册提供了在实地调查期间保护机密信息的实用方法。","targetForm":"practical","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"preside":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"主持"}],"examples":[{"sentence":"The dean will preside over the ceremony and welcome the visiting scholars.","translation":"院长将主持典礼并欢迎来访学者。","targetForm":"preside","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"A retired judge presided over the debate to ensure that every speaker received equal time.","translation":"一位退休法官主持辩论，以确保每位发言者获得相同的时间。","targetForm":"presided","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The chair presides over monthly meetings where staff discuss safety concerns openly.","translation":"主席主持每月会议，员工在会上公开讨论安全问题。","targetForm":"presides","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"During the final session, an independent mediator will preside over negotiations between the two groups.","translation":"在最后一次会议期间，一名独立调解员将主持两组之间的谈判。","targetForm":"preside","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"She learned to preside calmly over crowded meetings without allowing minor disputes to derail them.","translation":"她学会了冷静主持拥挤的会议，不让小争执使会议偏离正轨。","targetForm":"preside","senseId":"source-v-3","sourceSenseId":"v-3"}]},"praise":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"表扬"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"赞美"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"称赞"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"赞扬"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"称赞"}],"examples":[{"sentence":"The supervisor praised the team for reporting the error before it affected customers.","translation":"主管表扬了团队，因为他们在错误影响客户前就进行了报告。","targetForm":"praised","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Public praise made the young volunteer more confident about leading future activities.","translation":"公开的赞扬让这名年轻志愿者更有信心带领今后的活动。","targetForm":"praise","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The review offers measured praise while also identifying several weaknesses in the study.","translation":"这篇评论在肯定研究优点的同时，也指出了其中的几个不足。","targetForm":"praise","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Parents should praise effort as well as achievement when children are learning difficult skills.","translation":"孩子学习困难技能时，父母应当肯定他们的努力，也要肯定他们的成绩。","targetForm":"praise","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"His colleagues praised the clarity of the presentation rather than its expensive design.","translation":"同事称赞的是演示的清晰度，而不是它昂贵的设计。","targetForm":"praised","senseId":"source-v-1","sourceSenseId":"v-1"}]},"protest":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"抗议"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"抗议"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"反对"}],"examples":[{"sentence":"Students organized a peaceful protest after the council announced cuts to the local bus service.","translation":"市政会宣布削减本地公交服务后，学生组织了一场和平抗议。","targetForm":"protest","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Thousands joined the protest, although the police kept the surrounding streets open.","translation":"数千人加入抗议活动，但警方仍保持周边街道畅通。","targetForm":"protest","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The workers protested against unsafe conditions at the construction site.","translation":"工人抗议建筑工地上不安全的工作条件。","targetForm":"protested","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Several residents wrote letters to protest the planned closure of the health centre.","translation":"几位居民写信反对计划关闭这家卫生中心。","targetForm":"protest","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Her protest was not about the fee itself but about the lack of prior notice.","translation":"她抗议的不是费用本身，而是事先没有得到通知。","targetForm":"protest","senseId":"source-n-1","sourceSenseId":"n-1"}]},"prosecute":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"起诉"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"从事"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"彻底进行"},{"id":"source-v-6","partOfSpeech":"v.","sourceSenseIds":["v-6"],"sense":"作检察官"}],"examples":[{"sentence":"The district attorney decided to prosecute the corporation for environmental violations after a thorough investigation.","translation":"经过彻底调查后，地方检察官决定以环境违法行为起诉该公司。","targetForm":"prosecute","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"She was determined to prosecute her studies with unwavering dedication, despite the numerous challenges she faced.","translation":"尽管面临诸多挑战，她仍决心以坚定不移的奉献精神继续她的学业。","targetForm":"prosecute","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"The authorities have the power to prosecute individuals who commit fraud, ensuring justice is served.","translation":"当局有权对犯有欺诈行为的个人提起公诉，以确保正义得到伸张。","targetForm":"prosecute","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"He prosecuted the war effort with relentless energy, coordinating resources and strategies across multiple fronts.","translation":"他以不懈的精力推进战争行动，协调多条战线的资源和战略。","targetForm":"prosecuted","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The lawyer who prosecuted the case presented compelling evidence that led to a swift conviction.","translation":"提起公诉的律师出示了令人信服的证据，导致迅速定罪。","targetForm":"prosecuted","senseId":"source-v-6","sourceSenseId":"v-6"}]},"prepare":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"准备"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"筹备"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使在思想上有准备"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"调制"}],"examples":[{"sentence":"The team prepared a short briefing so that visitors could understand the purpose of the survey before taking part.","translation":"团队准备了一份简短说明，使访客在参与前能了解调查目的。","targetForm":"prepared","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the exhibition opens next month, the museum began to prepare the rooms long before the objects arrived.","translation":"尽管展览下个月开幕，博物馆早在物品到达前很久就开始准备展厅。","targetForm":"prepare","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The lecturer prepared students for difficult findings by explaining why the evidence might challenge familiar assumptions.","translation":"讲师通过解释证据为何可能挑战熟悉假设，使学生在思想上为困难发现做好准备。","targetForm":"prepared","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Before the test, technicians prepared the solution under controlled conditions and labelled every container clearly.","translation":"测试前，技术人员在受控条件下配制溶液，并清楚标记每个容器。","targetForm":"prepared","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"Because the discussion would be complex, the chair prepared questions that could help the group examine each claim carefully.","translation":"由于讨论会很复杂，主席准备了一些问题，帮助小组仔细审查每项主张。","targetForm":"prepared","senseId":"source-v-1","sourceSenseId":"v-1"}]},"prior":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"较早的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"更重要的"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"小隐修院院长"}],"examples":[{"sentence":"Prior research suggested a possible connection, but the new study examined a much larger group of participants.","translation":"先前研究提出了可能关联，但新研究考察了更大的参与者群体。","targetForm":"prior","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Although she had prior experience with the software, she still read the updated guidance before changing the records.","translation":"尽管她此前有使用该软件的经验，修改记录前仍阅读了更新说明。","targetForm":"prior","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The committee gave prior consideration to safety because the venue would be used by young children.","translation":"委员会优先考虑安全，因为场地将供儿童使用。","targetForm":"prior","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The prior welcomed visitors to the small monastery and explained the history of its library.","translation":"隐修院院长欢迎访客来到小修院，并解释其图书馆的历史。","targetForm":"prior","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Before the ceremony, the prior checked that every guest had received the correct programme.","translation":"仪式前，隐修院院长检查每位来宾是否收到正确的节目单。","targetForm":"prior","senseId":"source-n-1","sourceSenseId":"n-1"}]},"prestige":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"声望"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"威望"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"声誉","contextReviewed":true},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"威信"}],"examples":[{"sentence":"The university's prestige attracts scholars from around the world, fostering a vibrant academic community.","translation":"这所大学的声望吸引了世界各地的学者，营造了充满活力的学术社区。","targetForm":"prestige","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Winning the Nobel Prize significantly enhanced the scientist's prestige within the international community.","translation":"获得诺贝尔奖大大提高了这位科学家在国际社会的威望。","targetForm":"prestige","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The company's long-standing prestige in the industry is built on decades of reliable service and innovation.","translation":"该公司在行业中的长期声誉建立在数十年的可靠服务和创新之上。","targetForm":"prestige","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"Although the position offered less salary, the prestige associated with it made the offer highly appealing.","translation":"尽管这个职位提供的薪水较低，但与之相关的声望使这个邀约极具吸引力。","targetForm":"prestige","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The diplomat's prestige enabled him to mediate effectively between the conflicting parties.","translation":"这位外交官的威信使他能够有效地在冲突各方之间进行调解。","targetForm":"prestige","senseId":"source-n-3","sourceSenseId":"n-3"}]},"profit":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"赢利"}],"examples":[{"sentence":"And, third, laws intended to protect private information should be reevaluated to ensure that IT companies are unable to profit from exploiting and manipulating it.","translation":"最重要的是，公众必须更加深刻地理解IT的经济效应，特别是改善了如此多的人的生活的技术如何只让如此少的人致富。","targetForm":"profit","senseId":"source-n-2","sourceSenseId":"n-2"}]},"preserve":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"保护"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"保存"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"保持"}],"examples":[{"sentence":"To preserve biodiversity, governments must enforce rules against deforestation, which threatens countless species.","translation":"为了保护生物多样性，政府必须执行针对森林砍伐的规定，因为砍伐威胁着无数物种。","targetForm":"preserve","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Digital archiving preserves fragile manuscripts by producing high-resolution copies and reducing the need for physical handling.","translation":"数字存档通过制作高分辨率副本来保存脆弱手稿，并减少对原件的接触。","targetForm":"preserves","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Although traditional crafts face commercial pressure, skilled artisans preserve them through apprenticeship programmes.","translation":"尽管传统手工艺面临商业压力，技艺精湛的工匠仍通过学徒制把它们保存下来。","targetForm":"preserve","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Freezing preserves food because it slows the growth of microorganisms that would otherwise cause spoilage.","translation":"冷冻能保存食物，因为它会减缓原本会导致腐败的微生物生长。","targetForm":"preserves","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The committee recommended that the city preserve the historic district because its character supports tourism and community identity.","translation":"委员会建议该市保护历史街区，因为其独特风貌有助于旅游业和社区认同。","targetForm":"preserve","senseId":"source-v-1","sourceSenseId":"v-1"}]},"prompt":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"迅速的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"立刻的"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"提示"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"提醒物"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"提示"}],"examples":[{"sentence":"Although the manager expected a prompt decision, the committee needed more time to review the evidence.","translation":"尽管经理期待迅速作出决定，委员会仍需要更多时间审查证据。","targetForm":"prompt","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because prompt delivery of medical supplies is essential, the organization invested in a reliable logistics network.","translation":"由于医疗物资及时送达至关重要，该机构投资建立了可靠的物流网络。","targetForm":"prompt","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"When the teacher gave a clear writing prompt, students could organize their essays more effectively.","translation":"老师给出清晰的写作提示后，学生能够更有效地组织文章。","targetForm":"prompt","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The update added a prompt that reminds users to save their work before closing the program.","translation":"这次更新增加了一项提示，在关闭程序前提醒用户保存工作。","targetForm":"prompt","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The coach prompted the quiet player to explain the strategy, thereby giving the whole team a clearer plan.","translation":"教练提示那名沉默的队员说明策略，从而让全队拥有更清晰的计划。","targetForm":"prompted","senseId":"source-v-3","sourceSenseId":"v-3"}]},"primitive":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"原始的"}],"examples":[{"sentence":"The primitive tools found at the site suggest that early humans had strong problem-solving abilities.","translation":"遗址中发现的原始工具表明，早期人类具备很强的解决问题能力。","targetForm":"primitive","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the device now seems primitive, it represented an important technical breakthrough when it was introduced.","translation":"尽管这台设备如今看来很原始，它在推出时仍代表了一项重要技术突破。","targetForm":"primitive","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Primitive agricultural methods could be sustainable, but they rarely supported the population densities that modern systems do.","translation":"原始农业方法可能具有可持续性，但很少能支撑现代体系所能承载的人口密度。","targetForm":"primitive","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Researchers argue that primitive art forms offer useful evidence about the cognitive development of early humans.","translation":"研究人员认为，原始艺术形式为了解早期人类的认知发展提供了有用证据。","targetForm":"primitive","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Before modern navigation, sailors relied on primitive instruments that required both skill and careful observation.","translation":"在现代导航出现前，水手依靠既需要技巧又需要细致观察的原始仪器。","targetForm":"primitive","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"probable":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"很可能的"}],"examples":[{"sentence":"Although the experiment is still in progress, the most probable outcome aligns with the initial hypothesis.","translation":"尽管实验仍在进行，最可能的结果与最初的假设一致。","targetForm":"probable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because the patient exhibited all the classic symptoms, the physician considered a viral infection the most probable diagnosis.","translation":"由于患者表现出所有典型症状，医生认为病毒感染是最可能的诊断。","targetForm":"probable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"If current emission trends continue, a rise in global temperatures of more than two degrees becomes increasingly probable.","translation":"如果当前的排放趋势持续下去，全球气温上升超过两度就变得越来越可能。","targetForm":"probable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The committee concluded that a compromise was the only probable path to securing bipartisan support.","translation":"委员会得出结论，妥协是获得两党支持唯一可能的途径。","targetForm":"probable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Given the steady decline in birth rates, it is highly probable that the population will shrink over the next two decades.","translation":"鉴于出生率持续下降，未来二十年人口很可能会减少。","targetForm":"probable","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"prosperous":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"繁盛的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"成功的"}],"examples":[{"sentence":"Although the nation faced economic downturns, investment in innovation helped create a prosperous and resilient economy.","translation":"尽管这个国家经历经济衰退，对创新的投入帮助它形成繁荣而有韧性的经济。","targetForm":"prosperous","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"A prosperous society requires not only material wealth but also social cohesion that encourages trust.","translation":"繁荣的社会不仅需要物质财富，也需要能促进信任的社会凝聚力。","targetForm":"prosperous","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because the government invested in education and infrastructure, the region became a prosperous trade centre.","translation":"由于政府投资教育和基础设施，该地区成为繁荣的贸易中心。","targetForm":"prosperous","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"While some cities depend on one industry, prosperous urban centres diversify their economies for stability.","translation":"有些城市依赖单一产业，繁荣的城市中心则通过经济多元化保持稳定。","targetForm":"prosperous","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The entrepreneur adopted sustainable practices, thereby making the business both responsible and prosperous.","translation":"这位企业家采用可持续做法，从而使企业既负责任又繁荣。","targetForm":"prosperous","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"progressive":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"改革论者"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"进步论者"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"累进的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"进步的"}],"examples":[{"sentence":"The progressives in the early twentieth century advocated for significant social reforms, including women's suffrage and labor rights.","translation":"二十世纪初的改革论者主张重大社会变革，包括妇女选举权和劳工权利。","targetForm":"progressives","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Many progressives believe that technological innovation will inevitably lead to a more equitable society.","translation":"许多进步论者相信技术创新将不可避免地带来更公平的社会。","targetForm":"progressives","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The company adopted a progressive policy that gradually increased employee benefits based on years of service.","translation":"公司采取了一项累进政策，根据服务年限逐步增加员工福利。","targetForm":"progressive","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Her progressive views on education emphasized critical thinking over rote memorization, which inspired many teachers.","translation":"她关于教育的进步观点强调批判性思维而非死记硬背，这启发了许多教师。","targetForm":"progressive","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The progressive movement in art challenged traditional aesthetics and embraced new forms of expression.","translation":"艺术领域的进步运动挑战了传统美学，并接纳了新的表现形式。","targetForm":"progressive","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"proposition":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"主张"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"命题"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"向...提议"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"向...提出猥亵的要求"}],"examples":[{"sentence":"The central proposition of the theory is that economic growth depends largely on technological innovation.","translation":"该理论的核心主张是，经济增长很大程度上依赖技术创新。","targetForm":"proposition","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Before accepting the proposition that smaller classes benefit every student, we should examine the evidence.","translation":"在接受小班教学惠及每位学生这一主张前，我们应审视证据。","targetForm":"proposition","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"In formal logic, a proposition is a statement that can be true or false but not both.","translation":"在形式逻辑中，命题是可以为真或为假的陈述，但不能同时为真和假。","targetForm":"proposition","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The director will proposition several retailers about a partnership that could expand regional distribution.","translation":"董事将向几家零售商提出合作建议，以扩大地区分销网络。","targetForm":"proposition","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"When the employee reported that a manager had propositioned her, the organisation began an independent investigation.","translation":"当该员工报告一名经理曾向她提出不当要求时，机构启动了独立调查。","targetForm":"propositioned","senseId":"source-v-2","sourceSenseId":"v-2"}]},"prayer":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"祈祷"}],"examples":[{"sentence":"The monk dedicated his life to prayer and meditation, thereby seeking inner peace rather than worldly success.","translation":"这位僧侣将一生奉献给祈祷和冥想，从而寻求内心的平静而非世俗的成功。","targetForm":"prayer","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The community held a prayer service, which was organized to honor the memory of those who had sacrificed their lives.","translation":"社区举行了一场祈祷仪式，旨在纪念那些牺牲生命的人。","targetForm":"prayer","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although she was not religious, she found that a moment of silent prayer each morning helped her focus throughout the day.","translation":"尽管她不信教，但她发现每天早晨片刻的默祷有助于她全天集中注意力。","targetForm":"prayer","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In many cultures, prayer is not only a personal act of devotion but also a communal ritual that strengthens social bonds.","translation":"在许多文化中，祈祷不仅是个人的虔诚行为，也是加强社会纽带的集体仪式。","targetForm":"prayer","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the patient's family believed in the power of collective prayer, they requested that friends and relatives join them in a vigil.","translation":"由于病人家属相信集体祈祷的力量，他们请求亲友加入守夜祈祷。","targetForm":"prayer","senseId":"source-n-1","sourceSenseId":"n-1"}]},"precedent":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"先例"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"在先的"}],"examples":[{"sentence":"The court's decision set a legal precedent that would influence similar cases for decades.","translation":"法院的裁决确立了一个法律先例，将在未来几十年影响类似案件。","targetForm":"precedent","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"There is no historical precedent for such a rapid shift in global economic power.","translation":"全球经济实力如此迅速的转移在历史上并无先例。","targetForm":"precedent","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The committee reviewed precedent cases to ensure consistency in their ruling.","translation":"委员会审查了先前的案例，以确保其裁决的一致性。","targetForm":"precedent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The precedent agreement between the two nations provided a framework for the current negotiations.","translation":"两国之间先前的协议为当前的谈判提供了框架。","targetForm":"precedent","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The judge cited a precedent condition that must be met before the contract becomes binding.","translation":"法官援引了一项先决条件，该条件必须在合同生效前得到满足。","targetForm":"precedent","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"primary":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"最主要者"}],"examples":[{"sentence":"CAMBRIDGE – In the French Republican party’s presidential primary on Sunday, François Fillon soundly defeated frontrunner Alain Juppé, winning close to 67% of the votes.","translation":"剑桥 — — 在星期天进行的法国共和党总统初选中，弗朗索瓦·菲永以赢得67%选票的成绩毫无争议地击败了领跑者阿兰·朱佩。","targetForm":"primary","senseId":"source-n-1","sourceSenseId":"n-1"}]},"provide":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"提供"}],"examples":[{"sentence":"Mentorship programmes provide young professionals with guidance for navigating demanding career paths.","translation":"导师计划为年轻专业人士提供指导，帮助他们应对充满挑战的职业道路。","targetForm":"provide","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because public libraries provide free access to information, they reduce educational inequality and support lifelong learning.","translation":"由于公共图书馆提供免费信息获取渠道，它们减少教育不平等并支持终身学习。","targetForm":"provide","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Governments that provide comprehensive safety nets are better able to protect vulnerable people during downturns.","translation":"提供全面社会保障网的政府，更能在经济下滑时保护弱势群体。","targetForm":"provide","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"While new technologies provide convenience, they also create ethical questions that require careful regulation.","translation":"尽管新技术提供便利，它们也会带来需要谨慎监管的伦理问题。","targetForm":"provide","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"International research partnerships provide a platform for sharing knowledge and addressing global challenges more effectively.","translation":"国际研究合作提供知识共享平台，并能更有效地应对全球挑战。","targetForm":"provide","senseId":"source-v-1","sourceSenseId":"v-1"}]},"practically":{"senseGroups":[{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"几乎"}],"examples":[{"sentence":"In the digital age, practically every aspect of our lives is influenced by algorithms that shape our choices.","translation":"在数字时代，我们生活的几乎每个方面都受到塑造我们选择的算法的影响。","targetForm":"practically","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"The two theories are so similar that they are practically indistinguishable to anyone without specialized training.","translation":"这两种理论如此相似，以至于对于没有受过专门训练的人来说，它们几乎无法区分。","targetForm":"practically","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"Because the new policy streamlined procedures, the approval process became practically effortless for small businesses.","translation":"由于新政策简化了程序，审批过程对小企业来说几乎毫不费力。","targetForm":"practically","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"In some remote regions, access to clean water is practically nonexistent, which exacerbates health crises.","translation":"在一些偏远地区，清洁用水的获取几乎不存在，这加剧了健康危机。","targetForm":"practically","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"Although the task seemed daunting at first, with proper planning it proved practically manageable.","translation":"尽管这项任务起初看起来令人生畏，但通过适当的规划，它被证明几乎是可管理的。","targetForm":"practically","senseId":"source-adv-1","sourceSenseId":"adv-1"}]},"prevent":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"防止"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"妨碍"}],"examples":[{"sentence":"By fueling Japanese insecurity, US policy risks bringing about the very outcome – a return to militarism – that it aims to prevent.","translation":"美国的政策加剧了日本的不安全感，有可能导致美国旨在防止的结果 — — 军国主义。","targetForm":"prevent","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Unfortunately, there are three flaws in the FSB’s framework that will prevent it from being effectively applied to large global banks.","translation":"不幸的是，FSB的框架存在三大缺陷，这决定了其无法有效适用于全球性大银行。","targetForm":"prevent","senseId":"source-v-4","sourceSenseId":"v-4"}]},"production":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"生产"}],"examples":[{"sentence":"When costs for labor-intensive goods and services became too high in these countries, production was shifted elsewhere.","translation":"如今的开放国际贸易和投资体系使得公司能够把生产放在最有利于其国际竞争力的地方，中国本身也从中获益良多，现在，中国也开始转移劳动密集型产业了。","targetForm":"production","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Oil production does not matter; exports do, which means that announcements of increases in oil output are irrelevant for prices.","translation":"这表明OPEC成员国国和石油进口国的政策制定者们都不应该忘记：应对高油价的唯一方法就是维持高油价。","targetForm":"production","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Public policy that discriminates against and discourages vital innovations in food production is not policy that has the public’s interest at heart.","translation":"由此可见，那些敌视并压制在食品生产方面的重要革新的公共政策并不是真心维护民众利益的政策。","targetForm":"production","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Unless and until US consumption patterns change or a rebounding dollar increases oil production, Americans will bear the brunt of single-currency oil pricing.","translation":"除非并且直到美国人的消费模式发生改变或者美元反弹从而增加石油产量，美国人将首当其冲的受到石油用单一货币计价的影响。","targetForm":"production","senseId":"source-n-2","sourceSenseId":"n-2"}]},"provoke":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"激怒"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"煽动","contextReviewed":true},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"惹起"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"诱导"}],"examples":[{"sentence":"His dismissive remarks provoked the audience, leading to a heated debate during the conference.","translation":"他轻蔑的言论激怒了听众，导致会议期间发生了激烈的辩论。","targetForm":"provoked","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The editorial was designed to provoke readers into reconsidering their stance on the controversial issue.","translation":"这篇社论旨在煽动读者重新考虑他们对这一争议问题的立场。","targetForm":"provoke","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"The sudden policy change provoked widespread protests among the affected communities.","translation":"突然的政策变化激起了受影响社区的广泛抗议。","targetForm":"provoked","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Certain chemicals can provoke an allergic reaction in individuals with sensitive skin.","translation":"某些化学物质可能诱发敏感皮肤个体的过敏反应。","targetForm":"provoke","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The teacher's question was intended to provoke critical thinking rather than elicit a simple answer.","translation":"老师的问题旨在诱导批判性思维，而不是引出简单的答案。","targetForm":"provoke","senseId":"source-v-3","sourceSenseId":"v-3"}]},"prototype":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"原型"}],"examples":[{"sentence":"Although the prototype performed well in simulations, real-world testing revealed flaws that delayed the project.","translation":"尽管原型在模拟中表现良好，实际测试仍发现了延误项目的缺陷。","targetForm":"prototype","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The team built a prototype to demonstrate the concept, which helped persuade cautious investors to provide funding.","translation":"团队制作原型来展示概念，这帮助说服谨慎的投资者提供资金。","targetForm":"prototype","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the prototype used off-the-shelf components, it was affordable but not durable enough for mass production.","translation":"由于原型使用现成组件，它成本较低，但不够耐用，无法用于量产。","targetForm":"prototype","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When the prototype failed a safety inspection, engineers redesigned the core mechanism to meet regulations.","translation":"当原型未通过安全检查时，工程师重新设计了核心机制以符合规定。","targetForm":"prototype","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The prototype gave stakeholders a tangible model from which to offer concrete feedback rather than abstract opinions.","translation":"原型向利益相关者提供了有形模型，让他们能给出具体反馈而不是抽象意见。","targetForm":"prototype","senseId":"source-n-1","sourceSenseId":"n-1"}]},"proof":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"证据"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"证明"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"试验"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"防...的"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"校对"}],"examples":[{"sentence":"Although the witness was credible, the court required independent proof before reaching a conclusion.","translation":"尽管证人可信，法庭仍要求有独立证据才作出结论。","targetForm":"proof","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The revised data provide proof that early feedback can improve the quality of student writing.","translation":"修订后的数据证明，及时反馈能够提高学生写作的质量。","targetForm":"proof","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Before printing the catalogue, the museum approved a proof to check colours, captions, and page numbers.","translation":"印刷目录前，博物馆审定了一份校样，以核对颜色、说明文字和页码。","targetForm":"proof","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because the archive room is proof against water damage, rare documents can be stored there safely.","translation":"由于档案室能够防水，珍贵文献可以安全地存放在那里。","targetForm":"proof","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The editor proofed the final report carefully so that numerical errors would not reach the public.","translation":"编辑仔细校对了最终报告，以免数字错误流入公众视野。","targetForm":"proofed","senseId":"source-v-3","sourceSenseId":"v-3"}]},"precious":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"宝贵的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"珍贵的"}],"examples":[{"sentence":"While modern life offers many distractions, the precious moments of solitude allow us to reflect and recharge.","translation":"虽然现代生活提供了许多干扰，但宝贵的独处时刻让我们得以反思和充电。","targetForm":"precious","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the necklace was made of precious stones, its true value lay in the sentimental memories it held.","translation":"尽管这条项链由珍贵的宝石制成，但其真正价值在于它所承载的情感记忆。","targetForm":"precious","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because water is a precious resource in arid regions, communities have developed innovative conservation techniques.","translation":"因为水在干旱地区是一种宝贵的资源，社区开发了创新的保护技术。","targetForm":"precious","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The historian argued that precious historical documents must be preserved, not only for research but also for future generations.","translation":"历史学家认为，珍贵的历史文献必须被保存，不仅为了研究，也为了后代。","targetForm":"precious","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"When we consider the rapid loss of biodiversity, every remaining species becomes a precious part of our natural heritage.","translation":"当我们考虑到生物多样性的迅速丧失时，每一个幸存的物种都成为我们自然遗产中宝贵的一部分。","targetForm":"precious","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"princess":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"公主"}],"examples":[{"sentence":"To hide the fact that she's a princess, she disguised herself as a boy and escaped the palace.","translation":"她为了掩饰自己公主的身份，女扮男装，逃出了皇宫。","targetForm":"princess","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Your sister looks as noble as if she were a princess.","translation":"你妹妹看上去那么高贵，就像是个公主一样。","targetForm":"princess","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He lifted the beautiful princess and threw her into the sea.","translation":"他用力举起美丽的公主, 然后将她丢入海中。","targetForm":"princess","senseId":"source-n-1","sourceSenseId":"n-1"}]},"preclude":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"预先排除"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"阻止"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"预防"}],"examples":[{"sentence":"The lack of sufficient evidence precludes any definitive conclusion about the cause of the accident.","translation":"缺乏足够的证据排除了对事故原因得出任何明确结论的可能性。","targetForm":"precludes","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"His prior commitments precluded him from attending the international conference on climate change.","translation":"他先前的承诺使他无法参加关于气候变化的国际会议。","targetForm":"precluded","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The new regulations are designed to preclude any possibility of fraud in the financial system.","translation":"新法规旨在防止金融系统中出现任何欺诈的可能性。","targetForm":"preclude","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"A thorough risk assessment can preclude many potential hazards before they become serious problems.","translation":"彻底的风险评估可以在许多潜在危险变成严重问题之前将其排除。","targetForm":"preclude","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The contract's confidentiality clause precludes employees from discussing proprietary information with outsiders.","translation":"合同的保密条款禁止员工与外部人员讨论专有信息。","targetForm":"precludes","senseId":"source-v-3","sourceSenseId":"v-3"}]},"predominant":{"senseGroups":[{"id":"source-adj-5","partOfSpeech":"adj.","sourceSenseIds":["adj-5"],"sense":"主要的","contextReviewed":true}],"examples":[{"sentence":"Although digital media have expanded rapidly, television remains the predominant source of news for older generations.","translation":"尽管数字媒体迅速扩张，电视仍然是老一辈人获取新闻的主要来源。","targetForm":"predominant","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"In many developing countries, agriculture is the predominant sector of employment, which makes rural development policies essential for poverty reduction.","translation":"在许多发展中国家，农业是主要的就业部门，这使得农村发展政策对于减贫至关重要。","targetForm":"predominant","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"The predominant reason for the project's failure was a lack of clear communication among team members, rather than technical difficulties.","translation":"项目失败的主要原因在于团队成员之间缺乏清晰的沟通，而非技术困难。","targetForm":"predominant","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"While economic factors are important, the predominant influence on educational attainment is often the family environment in which a child grows up.","translation":"虽然经济因素很重要，但对教育成就的主要影响往往是孩子成长的家庭环境。","targetForm":"predominant","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"The survey revealed that the predominant concern among urban residents is air pollution, which has prompted the government to implement stricter emission standards.","translation":"调查显示，城市居民最主要的担忧是空气污染，这促使政府实施了更严格的排放标准。","targetForm":"predominant","senseId":"source-adj-5","sourceSenseId":"adj-5"}]},"principle":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"原则"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"原理"}],"examples":[{"sentence":"The principle of equal access guided the library when it redesigned services for disabled readers.","translation":"平等获取的原则指导图书馆为残障读者重新设计服务。","targetForm":"principle","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the decision was unpopular, the director defended it as a matter of principle.","translation":"尽管这个决定不受欢迎，主管仍把它视为原则问题而加以辩护。","targetForm":"principle","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When students understand the principle behind an equation, they can apply it in unfamiliar situations.","translation":"当学生理解方程背后的原理时，他们就能把它应用于不熟悉的情境。","targetForm":"principle","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because the principle of energy conservation is fundamental, engineers use it to check their calculations.","translation":"由于能量守恒原理是基础性的，工程师会用它检查计算结果。","targetForm":"principle","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The school adopted the principle that every complaint deserves a timely and respectful response.","translation":"学校采用了这样一项原则：每一项投诉都应得到及时且尊重的回应。","targetForm":"principle","senseId":"source-n-1","sourceSenseId":"n-1"}]},"prey":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"被掠食者"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"牺牲者"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"捕食"}],"examples":[{"sentence":"Predators help maintain ecological balance by controlling the population of their prey rather than eliminating it completely.","translation":"捕食者通过控制猎物数量而非完全消灭猎物，帮助维持生态平衡。","targetForm":"prey","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the gazelle is swift, it can still fall prey to a cheetah that relies on sudden acceleration.","translation":"尽管瞪羚速度很快，它仍可能成为依靠瞬间加速的猎豹的猎物。","targetForm":"prey","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Older people should be taught to recognise online scams so that they do not become prey to financial fraud.","translation":"应教会老年人识别网络诈骗，以免他们成为金融欺诈的受害者。","targetForm":"prey","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When an introduced species preys on native insects, it can disrupt food chains that have developed over centuries.","translation":"当外来物种捕食本地昆虫时，它可能破坏经过数百年形成的食物链。","targetForm":"preys","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The owl approaches its prey almost silently, which allows it to hunt successfully even in dense woodland.","translation":"猫头鹰几乎无声地接近猎物，使它即使在茂密林地中也能成功捕猎。","targetForm":"prey","senseId":"source-n-1","sourceSenseId":"n-1"}]},"preface":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"前言"}],"examples":[{"sentence":"To preface his argument, the scholar cited several historical precedents that illustrate the long-term consequences of environmental neglect.","translation":"为了引出他的论点，这位学者引用了几个历史先例，说明忽视环境的长期后果。","targetForm":"preface","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because a thoughtful preface can establish credibility and engage the audience, authors should invest time in crafting a compelling opening.","translation":"由于一篇深思熟虑的序言能建立可信度并吸引读者，作者应投入时间撰写一个引人入胜的开篇。","targetForm":"preface","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The editor's preface not only summarizes the key themes of the anthology but also explains the selection criteria for the included works.","translation":"编辑的序言不仅总结了选集的关键主题，还解释了入选作品的选择标准。","targetForm":"preface","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"In the preface to her memoir, the author reflects on the transformative power of education, which shaped her journey from poverty to success.","translation":"在她的回忆录序言中，作者反思了教育的变革力量，这塑造了她从贫困走向成功的历程。","targetForm":"preface","senseId":"source-n-3","sourceSenseId":"n-3"}]},"professional":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"专业人才"}],"examples":[{"sentence":"And, of course, Japan’s Self Defense Forces are professional and under full civilian control.","translation":"当然，日本自卫队是专业人士，且处于日本民众的控制之下。","targetForm":"professional","senseId":"source-n-1","sourceSenseId":"n-1"}]},"priest":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"牧师"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"祭司"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"神父"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"僧侣"},{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"泰斗"}],"examples":[{"sentence":"The priest conducted the solemn ceremony with a quiet dignity that moved the entire congregation.","translation":"那位牧师以沉静的庄严主持了隆重的仪式，感动了全体会众。","targetForm":"priest","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"In many ancient cultures, priests were responsible for interpreting omens and offering sacrifices to the gods.","translation":"在许多古代文化中，祭司负责解读预兆并向神灵献祭。","targetForm":"priests","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The young priest devoted his life to serving the rural parish, where he was deeply respected by the villagers.","translation":"那位年轻的神父毕生服务于乡村教区，深受村民尊敬。","targetForm":"priest","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Buddhist priests in the monastery rise before dawn to chant sutras and meditate in the silent halls.","translation":"寺院里的僧侣们在黎明前起床，在寂静的殿堂中诵经冥想。","targetForm":"priests","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"The renowned scholar was regarded as a priest of modern physics, whose theories reshaped our understanding of the universe.","translation":"那位著名学者被视为现代物理学的泰斗，其理论重塑了我们对宇宙的理解。","targetForm":"priest","senseId":"source-n-6","sourceSenseId":"n-6"}]},"precede":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"在...之前"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"在前面"}],"examples":[{"sentence":"A brief period of economic instability preceded the country's remarkable recovery in the following decade.","translation":"短暂的经济不稳定时期先于该国随后十年的显著复苏。","targetForm":"preceded","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The introduction of the new policy was preceded by months of public consultation and expert review.","translation":"新政策的出台之前是数月的公众咨询和专家评审。","targetForm":"preceded","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"In the procession, the mayor preceded the visiting dignitaries as they entered the hall.","translation":"在游行队伍中，市长走在来访贵宾前面进入大厅。","targetForm":"preceded","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"In formal logic, the premise must precede the conclusion in a valid deductive argument.","translation":"在形式逻辑中，一个有效的演绎论证中前提必须先于结论。","targetForm":"precede","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The chairman's opening remarks preceded the keynote address, setting the tone for the entire conference.","translation":"主席的开场致辞先于主旨演讲，为整个会议定下了基调。","targetForm":"preceded","senseId":"source-v-1","sourceSenseId":"v-1"}]},"proportion":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"比例"}],"examples":[{"sentence":"Men's wants become greater in proportion to the increase in their income.","translation":"人收入愈高，欲望就愈大。","targetForm":"proportion","senseId":"source-n-1","sourceSenseId":"n-1"}]},"print":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"打印"}],"examples":[{"sentence":"It will be able to edit the pictures you don't like, then print them out.","translation":"它可以将你不喜欢的照片修好，然后在印出来。","targetForm":"print","senseId":"source-n-1","sourceSenseId":"n-1"}]},"procedure":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"程序"}],"examples":[{"sentence":"You may injure yourself if you don't follow safety procedures.","translation":"如果你不按照安全手续来的话，你可能会受伤的。","targetForm":"procedures","senseId":"source-n-1","sourceSenseId":"n-1"}]},"profound":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"深刻的"}],"examples":[{"sentence":"Whoever becomes South Korea’s next president will be greeted by profound political, economic, and foreign policy challenges.","translation":"不论谁成为韩国下任总统，都将面临严峻的政治、经济和外交政策挑战。","targetForm":"profound","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"prince":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"王子"}],"examples":[{"sentence":"In the fairy tale, the prince broke the curse by demonstrating true love, thereby saving the entire kingdom.","translation":"在童话中，王子通过展现真爱打破了诅咒，从而拯救了整个王国。","targetForm":"prince","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the prince was known for his diplomatic skills, he was often sent to negotiate treaties with neighboring kingdoms.","translation":"因为王子以外交技巧闻名，他经常被派去与邻国谈判条约。","targetForm":"prince","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The prince, who had studied environmental science, advocated for sustainable policies when he became king.","translation":"这位曾学习环境科学的王子在成为国王后倡导可持续政策。","targetForm":"prince","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the prince was born into royalty, he chose to serve as a military officer to understand his people's struggles.","translation":"尽管王子出身皇室，他选择担任军官以了解人民的疾苦。","targetForm":"prince","senseId":"source-n-1","sourceSenseId":"n-1"}]},"preliminary":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"预试"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"初步的"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"预选赛"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"初步措施"}],"examples":[{"sentence":"The researchers treated the first trial as a preliminary, because its purpose was to identify weaknesses in the questionnaire.","translation":"研究人员把第一次试验当作预试，因为它的目的是找出问卷中的不足。","targetForm":"preliminary","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although the preliminary results are encouraging, the authors caution that the sample is too small for a firm conclusion.","translation":"尽管初步结果令人鼓舞，作者仍提醒样本太小，不能得出确定结论。","targetForm":"preliminary","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"She advanced through the preliminary after adjusting her pace, which left her enough energy for the final round.","translation":"她调整节奏后通过了预选赛，从而为决赛保留了足够体力。","targetForm":"preliminary","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"As a preliminary measure, the council published the consultation timetable before making any binding decision.","translation":"作为初步措施，委员会在作出任何具有约束力的决定前公布了咨询时间表。","targetForm":"preliminary","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The preliminary review revealed missing records, so the auditors delayed their findings until the archive could be checked.","translation":"初步审查发现档案缺失，因此审计人员推迟发布结论，直到档案能够核查。","targetForm":"preliminary","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"pretend":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"假装"}],"examples":[{"sentence":"In academic writing, one should never pretend to understand a theory without thoroughly examining the evidence.","translation":"在学术写作中，一个人绝不应该在没有彻底审查证据的情况下假装理解一个理论。","targetForm":"pretend","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"To avoid hurting his colleague's feelings, he had to pretend that he admired the flawed proposal.","translation":"为了避免伤害同事的感情，他不得不假装欣赏那份有缺陷的提案。","targetForm":"pretend","senseId":"source-v-1","sourceSenseId":"v-1"}]},"private":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"私人的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"秘密的"}],"examples":[{"sentence":"But low-income countries’ access to private lenders comes with risks that should be highlighted at the outset, before they grow into imminent threats.","translation":"但低收入国家得以接触私人贷款人也带来了风险，这一风险从一开始 — — 在它们演变为重大威胁之前 — — 就应该得到高度重视。","targetForm":"private","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Clearly, a new approach is needed – one that capitalizes on the comparative advantages of the private sector, state authorities, and the federal government.","translation":"显然，我们需要新方针 — — 利用私人部门、州有关部门和联邦政府的比较优势的方针。","targetForm":"private","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"And, third, laws intended to protect private information should be reevaluated to ensure that IT companies are unable to profit from exploiting and manipulating it.","translation":"最重要的是，公众必须更加深刻地理解IT的经济效应，特别是改善了如此多的人的生活的技术如何只让如此少的人致富。","targetForm":"private","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"prejudice":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"偏见"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"侵害"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使存偏见"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"侵害"}],"examples":[{"sentence":"Prejudice can persist when people rely on second-hand assumptions rather than speaking with those whose experiences differ from theirs.","translation":"当人们依赖二手假设，而非与经历不同的人交流时，偏见就可能持续存在。","targetForm":"prejudice","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The programme addresses prejudice by teaching students to examine how stereotypes influence their first impressions.","translation":"该项目通过教学生审视刻板印象如何影响第一印象，来应对偏见。","targetForm":"prejudice","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The delayed announcement caused no prejudice to applicants because the deadline was extended for everyone equally.","translation":"延期公告没有损害申请者的利益，因为所有人的截止日期都被同等延长。","targetForm":"prejudice","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"A misleading headline may prejudice readers before they have considered the evidence presented in the article.","translation":"误导性的标题可能使读者在考察文章证据前就形成偏见。","targetForm":"prejudice","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The court postponed publication of the details so that publicity would not prejudice the fairness of the hearing.","translation":"法院推迟公布细节，以免舆论损害听证程序的公正性。","targetForm":"prejudice","senseId":"source-v-3","sourceSenseId":"v-3"}]},"probe":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"探测器"}],"examples":[{"sentence":"The space probe Lucy is expected to arrive in 2025 to the proximity of the asteroid Donaldjohanson.","translation":"太空探测器露西预计将于 2025 年抵达小行星唐纳德约翰逊附近。","targetForm":"probe","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Vikings 1 and 2 became the first space probes to successfully land on the surface of Mars.","translation":"维京1号和2号成为了最先在火星表面成功着陆的空间探测器。","targetForm":"probes","senseId":"source-n-4","sourceSenseId":"n-4"}]},"province":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"省"}],"examples":[{"sentence":"Because the province implemented strict environmental regulations, air quality has improved significantly over the past five years.","translation":"由于该省实施了严格的环境法规，过去五年空气质量显着改善。","targetForm":"province","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Sichuan province, which is famous for its spicy cuisine and giant pandas, attracts millions of tourists each year.","translation":"四川省以其辛辣美食和大熊猫而闻名，每年吸引数百万游客。","targetForm":"province","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The cultural traditions of this province, which include unique folk dances and festivals, have been preserved for centuries.","translation":"该省的文化传统，包括独特的民间舞蹈和节日，已经保存了几个世纪。","targetForm":"province","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While the central government oversees national defense, each province is responsible for managing its own education and healthcare systems.","translation":"虽然中央政府负责国防，但每个省负责管理自己的教育和医疗系统。","targetForm":"province","senseId":"source-n-1","sourceSenseId":"n-1"}]},"pronoun":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"代词"}],"examples":[{"sentence":"A pronoun can make a paragraph smoother, provided that readers can identify the noun it refers to.","translation":"代词可以让段落更流畅，前提是读者能辨认它所指的名词。","targetForm":"pronoun","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When a pronoun has two possible antecedents, the writer should replace it with the intended noun.","translation":"当一个代词有两个可能的先行词时，作者应把它换成所要指代的名词。","targetForm":"pronoun","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The editor checked every pronoun because an unclear reference can make a carefully argued sentence difficult to follow.","translation":"编辑检查了每一个代词，因为指代不清会使论证严谨的句子难以理解。","targetForm":"pronoun","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although a pronoun avoids repetition, it should not be used where a more specific word would improve precision.","translation":"尽管代词能避免重复，在更具体的词能提高精确性的地方却不应使用它。","targetForm":"pronoun","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The grammar exercise asks students to explain why each pronoun agrees with its antecedent in context.","translation":"这项语法练习要求学生说明每个代词为何在语境中与其先行词一致。","targetForm":"pronoun","senseId":"source-n-1","sourceSenseId":"n-1"}]},"prosper":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"繁荣"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"成功"}],"examples":[{"sentence":"Small businesses can prosper when reliable transport allows them to reach customers beyond the immediate neighbourhood.","translation":"当可靠交通使小企业能触及社区以外的顾客时，它们可以繁荣发展。","targetForm":"prosper","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the region lacks large industries, it has prospered by combining local craft traditions with sustainable tourism.","translation":"尽管该地区缺少大型工业，它仍通过结合本地工艺传统和可持续旅游实现繁荣。","targetForm":"prospered","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The partnership prospered because each organisation contributed a different skill rather than duplicating work already being done.","translation":"这项合作之所以成功，是因为每个组织贡献不同技能，而不是重复已经完成的工作。","targetForm":"prospered","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Clear rules and independent review can help a new field prosper by giving responsible innovators confidence to invest.","translation":"清晰规则和独立审查可帮助新领域发展，让负责任的创新者有信心投资。","targetForm":"prosper","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The programme was designed so that local enterprises could prosper while the benefits of growth reached smaller communities.","translation":"该项目旨在让本地企业发展，同时确保增长的收益惠及较小社区。","targetForm":"prosper","senseId":"source-v-1","sourceSenseId":"v-1"}]},"presently":{"senseGroups":[{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"目前"}],"examples":[{"sentence":"It is presently very difficult to calm down and treat oneself with a book.","translation":"现在很难静下心来好好看一本书。","targetForm":"presently","senseId":"source-adv-1","sourceSenseId":"adv-1"}]},"priority":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"优先"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"优先权"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"计算机中的优先级","contextReviewed":true}],"examples":[{"sentence":"The council gave priority to repairing the water network, because failures there affected schools, homes, and local businesses.","translation":"委员会优先修复供水网络，因为那里的故障影响学校、家庭和当地企业。","targetForm":"priority","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although every request was urgent to someone, the manager asked the team to identify one clear priority for the week.","translation":"尽管每个请求对某些人都紧急，经理仍要求团队确定本周一项明确优先事项。","targetForm":"priority","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Children with immediate housing needs received priority in the allocation process, which made the criteria more transparent.","translation":"有紧急住房需求的儿童在分配流程中享有优先权，这使标准更加透明。","targetForm":"priority","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The scheduler assigned higher priority to security updates so that critical fixes would not wait behind routine maintenance.","translation":"调度器为安全更新分配更高优先级，使关键修复不会排在日常维护之后。","targetForm":"priority","senseId":"source-other-1","sourceSenseId":"other-1"},{"sentence":"If everything is treated as a priority, the team loses the ability to decide what can safely be postponed.","translation":"若所有事情都被当作优先事项，团队便失去判断哪些工作可以安全推迟的能力。","targetForm":"priority","senseId":"source-n-2","sourceSenseId":"n-2"}]},"prospective":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"将来的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"预期的"}],"examples":[{"sentence":"Prospective graduate students should thoroughly research potential supervisors, because a supportive mentor can greatly influence their academic trajectory.","translation":"未来的研究生应该彻底研究潜在的导师，因为一位支持性的导师可以极大地影响他们的学术轨迹。","targetForm":"prospective","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Universities often organize campus tours for prospective students, thereby allowing them to experience the academic environment and facilities firsthand.","translation":"大学经常为未来的学生组织校园参观，从而使他们能够亲身体验学术环境和设施。","targetForm":"prospective","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"A detailed market analysis enables prospective entrepreneurs to identify gaps in the industry, which can lead to innovative business opportunities.","translation":"详细的市场分析使潜在企业家能够发现行业中的空白，从而带来创新的商业机会。","targetForm":"prospective","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Although the company offered a competitive salary, the prospective employee hesitated due to concerns about work-life balance and corporate culture.","translation":"尽管公司提供了有竞争力的薪水，但这位潜在员工因担心工作与生活的平衡以及企业文化而犹豫不决。","targetForm":"prospective","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"When evaluating prospective investments, it is essential to consider not only the potential returns but also the associated risks and ethical implications.","translation":"在评估潜在投资时，不仅要考虑潜在回报，还要考虑相关风险和道德影响，这一点至关重要。","targetForm":"prospective","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"prisoner":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"囚犯"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"战俘"}],"examples":[{"sentence":"The report examined how education programmes can help a prisoner prepare for life after release.","translation":"报告考察了教育项目如何帮助囚犯为获释后的生活作准备。","targetForm":"prisoner","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the prisoner was held in a secure facility, the library service still delivered books for study.","translation":"尽管囚犯被关押在安全设施中，图书馆服务仍会为学习送去书籍。","targetForm":"prisoner","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The legal history course compared the rights of prisoners across different periods without focusing on individual cases.","translation":"法律史课程比较了不同时期囚犯的权利，而没有聚焦于个案。","targetForm":"prisoners","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The museum displayed letters written by a prisoner of war, placing them within their historical and humanitarian context.","translation":"博物馆展出了战俘写下的信件，并把它们置于历史和人道主义语境中。","targetForm":"prisoner","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Before publishing the archive, the editors removed details that could identify a former prisoner or family member.","translation":"发表档案前，编辑删除了可能识别出前囚犯或其家属的细节。","targetForm":"prisoner","senseId":"source-n-1","sourceSenseId":"n-1"}]},"privilege":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"特权"}],"examples":[{"sentence":"The privilege of working with renowned researchers gave the young scientist invaluable insights into cutting-edge methodologies, which accelerated her career.","translation":"与知名研究人员共事的特权让这位年轻科学家对前沿方法有了宝贵的见解，从而加速了她的职业生涯。","targetForm":"privilege","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Access to quality education is often considered a privilege rather than a universal right, which perpetuates social inequality in many regions.","translation":"获得优质教育往往被视为一种特权而非普遍权利，这在许多地区使社会不平等长期存在。","targetForm":"privilege","senseId":"source-n-1","sourceSenseId":"n-1"}]},"progress":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"进步"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"发展"}],"examples":[{"sentence":"The implication is clear: although Europe has made significant progress toward fiscal union, it remains far removed from political union.","translation":"影响显而易见：尽管欧洲朝着财政联盟的方向取得了重大进步，但距离政治联盟依然十分遥远。","targetForm":"progress","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A third key health trend in 2017 was further progress toward the elimination of human onchocerciasis, which causes blindness, impaired vision, and skin infections.","translation":"2017年的第三项关键性卫生趋势是消灭人类盘尾丝虫病的进程也实现了新的进展，人类盘尾丝虫病会造成失明、视力下降和皮肤感染。","targetForm":"progress","senseId":"source-n-2","sourceSenseId":"n-2"}]},"premise":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"前提"}],"examples":[{"sentence":"But while the premises underlying this broad trend are clear, Latin America’s voters are electing not one left, but two.","translation":"尽管这种大趋势作为前提已经再清楚不过，但拉丁美洲的投票者选出的却不是一个左派，而是两个。","targetForm":"premises","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The new policy was introduced on the premise that flexible working hours would boost employee productivity.","translation":"新政策的推出基于弹性工作时间能提高员工生产力这一前提。","targetForm":"premise","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"If the underlying premise is flawed, even the most rigorous methodology cannot yield valid conclusions.","translation":"如果基本前提有缺陷，即使最严谨的方法也无法得出有效的结论。","targetForm":"premise","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The company's expansion strategy was built on the premise that demand for electric vehicles would surge within five years.","translation":"公司的扩张战略建立在五年内电动汽车需求将激增这一前提之上。","targetForm":"premise","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Critics challenged the premise that standardized tests accurately measure a student's academic potential.","translation":"批评者质疑标准化考试能准确衡量学生学术潜力这一前提。","targetForm":"premise","senseId":"source-n-1","sourceSenseId":"n-1"}]},"proper":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"适当的"}],"examples":[{"sentence":"Bicycles wear out, of course, but with proper care they may be made to last a long time.","translation":"自行车当然会磨损，但只要你保养得好，就能骑很长一段时间。","targetForm":"proper","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"prose":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"散文"}],"examples":[{"sentence":"Our beloved father would read us some prose every week to better our understanding of the world's beauty.","translation":"我们亲爱的父亲每周都会给我们阅读散文，好让我们认识到世界的美好之处。","targetForm":"prose","senseId":"source-n-1","sourceSenseId":"n-1"}]},"promote":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"促进"}],"examples":[{"sentence":"That leads to the challenge of effective management of public assets – management that promotes rather than impedes market efficiency and innovation.","translation":"这就提出了对公共资产进行有效管理的挑战 — — 这种管理应该促进而不是妨碍市场效率和创新。","targetForm":"promotes","senseId":"source-v-1","sourceSenseId":"v-1"}]},"precise":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"精确的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"明确的"}],"examples":[{"sentence":"Establishing precise criteria for evaluating research proposals ensures that funding is allocated to the most promising projects.","translation":"制定精确的评估研究提案标准，确保资金分配给最有前景的项目。","targetForm":"precise","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"In legal documents, the use of precise language is essential to avoid ambiguity, thereby preventing potential disputes.","translation":"在法律文件中，使用精确的语言对于避免歧义至关重要，从而防止潜在争议。","targetForm":"precise","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Modern climate models require precise data on ocean temperatures, because accurate predictions depend on such details.","translation":"现代气候模型需要精确的海洋温度数据，因为准确的预测依赖于这些细节。","targetForm":"precise","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"programme":{"senseGroups":[{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"计划"}],"examples":[{"sentence":"Although the programme was initially underfunded, it eventually achieved remarkable results through community support.","translation":"尽管该计划最初资金不足，但通过社区支持，最终取得了显着成果。","targetForm":"programme","senseId":"source-n-6","sourceSenseId":"n-6"},{"sentence":"Because the training programme incorporated hands-on workshops, participants gained practical skills more effectively.","translation":"由于培训计划包含了实践工作坊，参与者更有效地获得了实用技能。","targetForm":"programme","senseId":"source-n-6","sourceSenseId":"n-6"},{"sentence":"Researchers developed an intervention programme to improve literacy, thereby enhancing overall academic performance.","translation":"研究人员制定了一项干预计划以提高读写能力，从而提升了整体学业表现。","targetForm":"programme","senseId":"source-n-6","sourceSenseId":"n-6"},{"sentence":"The government's new housing programme, which prioritizes low-income families, has significantly reduced homelessness.","translation":"政府的新住房计划优先考虑低收入家庭，显着减少了无家可归现象。","targetForm":"programme","senseId":"source-n-6","sourceSenseId":"n-6"}]},"prospect":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"展望"}],"examples":[{"sentence":"BERLIN – I am on a two-week European tour at a time that could make one either very pessimistic or constructively optimistic about Europe’s prospects.","translation":"柏林—我正在欧洲作为期两周的旅行，眼下，我对欧洲的前景既不特别悲观，也不建设性地乐观。","targetForm":"prospects","senseId":"source-n-2","sourceSenseId":"n-2"}]},"practise":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"练习"}],"examples":[{"sentence":"No, if you do not start practising from now onwards, it would be too late.","translation":"不，如果不从现在开始练习，就来不及了 。","targetForm":"practising","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"It's not that I don't like your English, but for me it's important to use every opportunity to practise Russian.","translation":"并不是我不喜欢你的英语，只是对我而言，利用每一个可能的机会来练习俄语很重要。","targetForm":"practise","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Tom spends most of his spare time practising the guitar.","translation":"汤姆把他大部分的空闲时间花在练习吉他上。","targetForm":"practising","senseId":"source-v-3","sourceSenseId":"v-3"}]},"press":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"压"}],"examples":[{"sentence":"Euro-zone countries reaffirmed their intention to press ahead with structural reforms across a broad front, in product, labor, and financial markets.","translation":"欧元区国家再次重申了它们决心继续在广泛的领域内，包括产品、劳动力和金融市场，推进结构改革。","targetForm":"press","senseId":"source-n-1","sourceSenseId":"n-1"}]},"prescribe":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"开处方"}],"examples":[{"sentence":"If Tom doesn't take the prescribed medicine, his state of health might deteriorate.","translation":"如果汤姆不服用处方药，他的健康状况可能会恶化。","targetForm":"prescribed","senseId":"source-v-4","sourceSenseId":"v-4"}]},"precision":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"精确"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"精确度"}],"examples":[{"sentence":"Our teacher is someone who likes precision, and always demands precise answers of her students.","translation":"老师性喜精准——她总是要求精确的答案。","targetForm":"precision","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Writer Luiz Fernando Veríssimo, a columnist capable of uniting generations of readers with irony, precision and sensitivity, died in Porto Alegre, Brazil.","translation":"作家路易斯・费尔南多・沃瑞西莫在巴西阿雷格里港去世，他是位专栏作家，能以讽刺、精确、敏感的文笔团结几代读者。","targetForm":"precision","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"This cartographer is famous for the precision in her maps.","translation":"此制图员出名于其制图的精准性。","targetForm":"precision","senseId":"source-n-3","sourceSenseId":"n-3"}]},"prove":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"证明"}],"examples":[{"sentence":"Europe deserves to prove that it is a real community, one diverse, democratic, spiritual, free, and prosperous.","translation":"欧洲应该证明自己是一个真正的社会，一个多元、民主、高尚、自由和繁荣的社会。","targetForm":"prove","senseId":"source-v-1","sourceSenseId":"v-1"}]},"predict":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"预知"}],"examples":[{"sentence":"Neither alternative is something that I would have predicted – or even imagined.","translation":"不管那种可能，都不是我此前所能预测的，甚至连想都不敢想。","targetForm":"predicted","senseId":"source-v-1","sourceSenseId":"v-1"}]},"prevalent":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"普遍的"}],"examples":[{"sentence":"It is a prevalent belief, according to a nationwide poll in the United States, that Muslims are linked with terrorism.","translation":"根据美国国民的一个投票，人们普遍认为穆斯林人和恐怖主义有关。","targetForm":"prevalent","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"professor":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"教授"}],"examples":[{"sentence":"We now know that the professor had broken into his own home, with the help of his chauffeur, because the door was jammed.","translation":"我们现在知道这位教授在司机的帮助下闯入了自家的房门，因为门被卡住了。","targetForm":"professor","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In his lectures, Professor Hunter prefers to study the blackboard rather than look at his students.","translation":"亨特教授在讲课时更喜欢盯着黑板看，而不是看学生。","targetForm":"professor","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She's a professor whose works you could stack up to head height.","translation":"那位是一个著作等身的教授。","targetForm":"professor","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He used to be a professor, but now he is the dean.","translation":"他以前是教授，后来当了系主任。","targetForm":"professor","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"By chance, I met my professor at a restaurant last night.","translation":"很巧， 昨天在饭馆里碰到了我的教授。","targetForm":"professor","senseId":"source-n-1","sourceSenseId":"n-1"}]},"prudent":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"审慎的"}],"examples":[{"sentence":"A miser hoards money not because he is prudent but because he is greedy.","translation":"守财奴积聚钱财不是因为他谨慎，而是因为他贪婪。","targetForm":"prudent","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"propose":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"计划"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"建议"}],"examples":[{"sentence":"There is another way to do that, and it is far cheaper than what Musk has proposed.","translation":"要想实现目标其实还有另外一种方法，而且比马斯克的计划要廉价得多。","targetForm":"proposed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"This is my appeal to our leaders, and to all of us, for 2015: Let us think, propose, and act together.","translation":"在2015年，我呼吁我们的领导人和我们所有人：让我们一起思考、建议和行动。","targetForm":"propose","senseId":"source-v-3","sourceSenseId":"v-3"}]},"pronounce":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"发音"}],"examples":[{"sentence":"When used as a Chinese surname, the character 林 is pronounced Lín; as a Japanese surname, it is read Hayashi.","translation":"林字作为中国姓氏，就读Lín；作为日本姓氏，则读Hayashi。","targetForm":"pronounced","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"People shouldn't be allowed to invade countries whose names they can't pronounce correctly.","translation":"人们不应该侵犯自己读不正确名字的国家。","targetForm":"pronounce","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"In the English language many words contain letters which are not pronounced.","translation":"英文里面很多字的字母是不发音的。","targetForm":"pronounced","senseId":"source-v-1","sourceSenseId":"v-1"}]},"practitioner":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"从业者"}],"examples":[{"sentence":"In the end, both camps should show greater humility: macro-development practitioners about what they already know, and micro-development practitioners about what they can learn.","translation":"最后，两大阵营应该更加谦逊：宏观发展实践者不能思而不学，微观发展实践者不能学而不思。","targetForm":"practitioners","senseId":"source-n-1","sourceSenseId":"n-1"}]},"pronunciation":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"发音"}],"examples":[{"sentence":"It's not your mother tongue, so your pronunciation will never be accurate.","translation":"因为它不是你的母语，你的发音会永远不准。","targetForm":"pronunciation","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"There are great differences in pronunciation between different Chinese dialects.","translation":"汉语方言间的发音区别很大。","targetForm":"pronunciation","senseId":"source-n-1","sourceSenseId":"n-1"}]},"preparation":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"准备"}],"examples":[{"sentence":"I bought a house on a small hill in southern France in preparation of building a retirement home.","translation":"我在法国南边的一座小山买了一所房子，准备在那里建设老人院。","targetForm":"preparation","senseId":"source-n-1","sourceSenseId":"n-1"}]},"pride":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"骄傲"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"自尊心"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"自豪"}],"examples":[{"sentence":"A gleam of real pride quickened most ingenuously in the Older Man's pale blue eyes.","translation":"老人淡蓝色的眼睛闪过一丝真诚的骄傲。","targetForm":"pride","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Hey, I may have no money, but I still have my pride.","translation":"嗨，我可能没钱，但我一直有我的骄傲。","targetForm":"pride","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"It was difficult for him to hide his pride in his success.","translation":"他很难掩饰对自己成功的骄傲。","targetForm":"pride","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"They spoke of their high exam grades with understandable pride.","translation":"他们很骄傲地谈到考试中的好成绩，这种骄傲是可以理解的。","targetForm":"pride","senseId":"source-n-3","sourceSenseId":"n-3"}]},"pray":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"祈祷"}],"examples":[{"sentence":"In Tbilisi, you can find the only mosque in the world where shia and sunni Muslims pray together.","translation":"在第比利斯，你可以看到世界上唯一一座什叶派和逊尼派穆斯林一起祈祷的清真寺。","targetForm":"pray","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"I've heard it said that English is for making money, French for making love, and Spanish for praying to God.","translation":"我听说英语是用来赚钱的，法语是用来做爱的，西班牙语是用来祈求上帝的。","targetForm":"praying","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"They knelt down and prayed that the war would end soon.","translation":"他们跪了下来祈祷，希望战争快点结束。","targetForm":"prayed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Let's pray he turns out to be a fast learner.","translation":"让我们祈祷他学得很快吧。","targetForm":"pray","senseId":"source-v-1","sourceSenseId":"v-1"}]},"protect":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"保护"}],"examples":[{"sentence":"At least two recent examples illustrate the potentially devastating effects of collective mechanisms for protecting savers despite a joint banking regulator.","translation":"至少有两个最近的例子可以说明保护储户的集体机制如何导致灾难性后果，哪怕存在联合银行监管当局。","targetForm":"protecting","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Another powerful measure would be to protect and restore natural ecosystems, which could result in the storage of 220-330 gigatons of CO2 worldwide .","translation":"另一项强力措施是保护和重建自然生态系统，这样可以储存2,200—3,300亿吨二氧化碳。","targetForm":"protect","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"And, third, laws intended to protect private information should be reevaluated to ensure that IT companies are unable to profit from exploiting and manipulating it.","translation":"最重要的是，公众必须更加深刻地理解IT的经济效应，特别是改善了如此多的人的生活的技术如何只让如此少的人致富。","targetForm":"protect","senseId":"source-v-2","sourceSenseId":"v-2"}]},"present":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"现在"}],"examples":[{"sentence":"Ghebreyesus’s candidacy presents the WHO with an historic opportunity, which its Executive Board should seize on January 25.","translation":"盖布勒耶瑟斯成为候选人是世卫组织的一次历史性机遇，其执行委员会应该在1月25日抓住这次机会。","targetForm":"presents","senseId":"source-n-1","sourceSenseId":"n-1"}]},"premier":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"总理"}],"examples":[{"sentence":"Because all of the teams in the Premier League are really strong, the goal difference is usually small.","translation":"因为在甲级联赛中，所有队伍都很有实力，净胜球差异很小。","targetForm":"premier","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"All the top teams of the UK are in the premier division.","translation":"英国所有的顶尖球队都在超级联赛中。","targetForm":"premier","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"All the top teams in England are in the Premier League.","translation":"英国所有的顶尖球队都在超级联赛中。","targetForm":"premier","senseId":"source-n-1","sourceSenseId":"n-1"}]},"process":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"程序"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"过程"}],"examples":[{"sentence":"One hopes that what emerges from the parties’ nominating processes is insight into how the successful candidates answer three big questions.","translation":"人们希望从两党提名程序中脱颖而出的是能深刻理解成功候选人如何回答这三大问题。","targetForm":"processes","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"This missing science would describe processes, and how entire systems evolve.","translation":"这种缺失的科学法则是用来描述过程，以及整个系统如何演化。","targetForm":"processes","senseId":"source-n-3","sourceSenseId":"n-3"}]},"prominent":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"卓越的"}],"examples":[{"sentence":"Prominent figures in the literary world gathered together last night.","translation":"知名文学界人士昨晚齐聚一堂。","targetForm":"prominent","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"presence":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"面前"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"存在"}],"examples":[{"sentence":"I told you not to mention that in her presence.","translation":"我跟你说过她在的时候不要说这件事。","targetForm":"presence","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"A special feature of verbs in the Russian language is the presence of the category of aspect.","translation":"俄语动词的一个特征是存在体的范畴。","targetForm":"presence","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"John felt the presence of a ghost in the dark room.","translation":"约翰感觉到那黑漆漆的房间里有鬼。","targetForm":"presence","senseId":"source-n-3","sourceSenseId":"n-3"}]},"preference":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"偏爱"}],"examples":[{"sentence":"But this change will raise challenging social and political questions as well, particularly concerning privacy preferences and health care – both already controversial issues.","translation":"但相关变化同样会引发社会政治难题，尤其是在已经争议颇多的隐私偏好和医疗保健领域。","targetForm":"preferences","senseId":"source-n-1","sourceSenseId":"n-1"}]},"price":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"价格"}],"examples":[{"sentence":"After the upward jump in energy prices in 1973, annual global growth fell from roughly 5% between 1960 and 1973 to around 3% between 1973 and 1989.","translation":"第二，全球经济比过去大很多，因此对关键商品和能源要素的需求也比过去大很多。","targetForm":"prices","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Oil production does not matter; exports do, which means that announcements of increases in oil output are irrelevant for prices.","translation":"这表明OPEC成员国国和石油进口国的政策制定者们都不应该忘记：应对高油价的唯一方法就是维持高油价。","targetForm":"prices","senseId":"source-n-1","sourceSenseId":"n-1"}]},"pressure":{"senseGroups":[{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"压力"}],"examples":[{"sentence":"So, while this latest bear-market rally may continue for a bit longer, renewed downward pressure on stocks and other risky assets is inevitable.","translation":"因此，尽管最近这次熊市反弹将持续更长时间，但股票和其他风险性资产必将重新感受到向下的压力。","targetForm":"pressure","senseId":"source-n-5","sourceSenseId":"n-5"}]},"previous":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"早先的"}],"examples":[{"sentence":"This year’s voting departed markedly from previous National Assembly elections in several other key respects, beyond the support shown for Macron’s new political grouping.","translation":"今年的选举与以往的国民大会选举有着不少关键性的差异，马克龙的新政治集团所赢得的支持只是其中之一。","targetForm":"previous","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"pretext":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"托词"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"借口"}],"examples":[{"sentence":"He came to my house on the pretext of seeing me.","translation":"他打着见我的幌子来了我家。","targetForm":"pretext","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Jonas left under the pretext of going to the bathroom.","translation":"乔纳斯以去洗手间为借口离开了。","targetForm":"pretext","senseId":"source-n-1","sourceSenseId":"n-1"}]},"prison":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"监狱"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"监禁"}],"examples":[{"sentence":"The Palestinian children that were arrested in June 2018 are being held in the Ofer prison.","translation":"2018 年 6 月被捕的巴勒斯坦儿童被关押在奥弗监狱。","targetForm":"prison","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Tom told me that he thought that he was going to die in prison.","translation":"汤姆告诉我他以为他会死在监狱里。","targetForm":"prison","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In some countries, the punishment for treason can be life in prison.","translation":"在一些国家，叛国罪的惩罚可以是终身监禁。","targetForm":"prison","senseId":"source-n-2","sourceSenseId":"n-2"}]},"provision":{"senseGroups":[{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"条款"}],"examples":[{"sentence":"Smart trade requires two key provisions: core labor rights, backed up by tough enforcement, and a development fund targeting infrastructure and education to boost competitiveness.","translation":"智能贸易要求具备两大关键条款：有严格的执法保障的核心劳工权益，以及针对基础设施与教育以增强竞争力的发展基金。","targetForm":"provisions","senseId":"source-n-5","sourceSenseId":"n-5"}]},"preach":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"讲道"}],"examples":[{"sentence":"The main duty of a priest is to preach in church.","translation":"牧师的主要职责是在教堂里讲道。","targetForm":"preach","senseId":"source-v-2","sourceSenseId":"v-2"}]},"prize":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"奖赏"}],"examples":[{"sentence":"NEW YORK – It must be galling for the Chinese government to keep seeing Nobel Prizes go to the wrong Chinese.","translation":"发自纽约 - - -眼看着诺贝尔奖一次次落入错误的中国人之手，中国政府一定感到怒不可遏吧。","targetForm":"prizes","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"After winning the Nobel prize, she remained as modest as ever.","translation":"获得诺贝尔奖后，她仍谦虚如昔。","targetForm":"prize","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The Nobel Prize is awarded annually on December 10, the day of Alfred Nobel's death.","translation":"诺贝尔奖在每年的十二月十日颁发，是Alfred Nobel去世的那天。","targetForm":"prize","senseId":"source-n-1","sourceSenseId":"n-1"}]},"president":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"总统"}],"examples":[{"sentence":"BERKELEY – Donald Trump’s first year as US president has been, if nothing else, a bounteous source of surprises.","translation":"伯克利—如果说特朗普当美国总统的第一年有什么特点的话，那就是充满了惊奇。","targetForm":"president","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"And yet, despite the hardship the sanctions will cause for ordinary Iranians, they are unlikely to deliver the outcomes that US President Donald Trump desires.","translation":"但尽管这些制裁会令伊朗民众的生活变得艰难，但却不太可能实现美国总统特朗普所寄望的结果。","targetForm":"president","senseId":"source-n-1","sourceSenseId":"n-1"}]},"proud":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"自豪的"}],"examples":[{"sentence":"He is proud that his father was a great scientist.","translation":"他很自豪他父亲是个伟大的科学家。","targetForm":"proud","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"She is proud that her son has become a doctor.","translation":"她为自己的儿子成为医生而自豪。","targetForm":"proud","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"project":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"计划"}],"examples":[{"sentence":"Any religious minority in quest of a place in the European project would do well to reflect on that theological shift.","translation":"任何宗教少数派在欧洲计划中探寻一席之地时，都会仔细考虑其在神学上的转变。","targetForm":"project","senseId":"source-n-1","sourceSenseId":"n-1"}]},"pregnant":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"怀孕的"}],"examples":[{"sentence":"Even if we don't get lucky on the first try we can just keep fucking till I get pregnant.","translation":"即使我们第一次不够幸运, 我们可以就一直做爱直到我怀孕。","targetForm":"pregnant","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"I got pregnant from the Finnish harpist that I told you about last night.","translation":"我跟那个芬兰竖琴手怀孕了，他就是我昨晚告诉你的那个人。","targetForm":"pregnant","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"However, it seems that just because it's a 'low risk day' doesn't mean that you won't get pregnant from intravaginal ejaculation.","translation":"但是，虽说是安全期，但好像也不代表体内射精不会怀孕。","targetForm":"pregnant","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Everyone was just flabbergasted that she was able to get pregnant at 48.","translation":"她48岁怀上了孩子，所有人都目瞪口呆。","targetForm":"pregnant","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"It's been said that one should not smell deer musk when pregnant.","translation":"据说怀孕的时候不能闻麝香。","targetForm":"pregnant","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"propaganda":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"宣传"}],"examples":[{"sentence":"Elon Musk embodies the conservative propaganda tactic of calling everyone who crosses you a pedophile.","translation":"伊隆马斯克将「凡是与你作对的人都是恋童癖」这一保守派惯用的抹黑手法发挥得淋漓尽致。","targetForm":"propaganda","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Tom wrote propaganda online without pay for the government, but cried when everyone in his hometown was massacred by the government.","translation":"汤姆在网上免费为政府写宣传，但他在他的家乡被政府屠杀时哭了。","targetForm":"propaganda","senseId":"source-n-1","sourceSenseId":"n-1"}]},"prohibit":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"禁止"}],"examples":[{"sentence":"The importation of rare wild animals to this country is strictly prohibited.","translation":"该国严禁进口稀有野生动物。","targetForm":"prohibited","senseId":"source-v-1","sourceSenseId":"v-1"}]},"promise":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"诺言"}],"examples":[{"sentence":"In fact, both the election and Petraeus’s resignation are pieces of a larger whole: an America that lives up to its promises.","translation":"事实上，大选和彼得雷乌斯的辞职都是更大图景的一部分：承诺立国的美国。","targetForm":"promises","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"If we keep our promises, 2006 can be a year of hope for those who have little else than the dream of a better life.","translation":"如果我们遵守诺言，2006年将成为那些除了对较好生活报有梦想外别无其他的人的希望之年。","targetForm":"promises","senseId":"source-n-1","sourceSenseId":"n-1"}]},"problem":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"难题"}],"examples":[{"sentence":"The unsolved problem is how to reduce those factors pushing people out of their own countries.","translation":"悬而未决的问题是如何遏制推动人们离开祖国的因素。","targetForm":"problem","senseId":"source-n-2","sourceSenseId":"n-2"}]},"privacy":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"隐私"}],"examples":[{"sentence":"But this change will raise challenging social and political questions as well, particularly concerning privacy preferences and health care – both already controversial issues.","translation":"但相关变化同样会引发社会政治难题，尤其是在已经争议颇多的隐私偏好和医疗保健领域。","targetForm":"privacy","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"More than 28 million Canadians were affected by privacy breaches last year.","translation":"去年，超过2800万加拿大人被隐私泄露受到影响了。","targetForm":"privacy","senseId":"source-n-1","sourceSenseId":"n-1"}]},"principal":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"校长"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"首长"}],"examples":[{"sentence":"The principal severely reproved the students whenever they made a mess in the hallway.","translation":"每次学生把走廊弄得一团糟的时候，校长都会严厉地训斥他们。","targetForm":"principal","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The principal theme of the book is the American Revolution.","translation":"这本书的主题是美国革命。","targetForm":"principal","senseId":"source-n-2","sourceSenseId":"n-2"}]},"pretty":{"senseGroups":[{"id":"source-adj-5","partOfSpeech":"adj.","sourceSenseIds":["adj-5"],"sense":"恰当的"}],"examples":[{"sentence":"I'm pretty sure Tom is the only one who can tell us what we need to know.","translation":"我很确定，汤姆是唯一能告诉我们我们需要知道的事情的人。","targetForm":"pretty","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"I have a pretty good idea who Tom will be hanging out with tonight.","translation":"我大概知道汤姆今晚会和谁一起玩。","targetForm":"pretty","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"I think Tom is going to be pretty mad when he finds out that the painting he bought is a fake.","translation":"我觉得当汤姆发现他买来的画是赝品的时候，他会很生气。","targetForm":"pretty","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"I got hurt during an experiment, and the injury was pretty serious.","translation":"我做实验的时候弄伤了，而且还伤得十分严重。","targetForm":"pretty","senseId":"source-adj-5","sourceSenseId":"adj-5"}]}}};
